import{k as u}from"./index-1Zu1i1DF.js";import{g as k}from"./cities-Ln69WsY-.js";const m=[["talon-maalaus","helsinki"],["talon-maalaus","espoo"],["talon-maalaus","vantaa"],["sisamaalaus","helsinki"],["sisamaalaus","espoo"],["sisamaalaus","vantaa"],["julkisivumaalaus","helsinki"],["julkisivumaalaus","espoo"],["julkisivumaalaus","vantaa"],["kattomaalaus","helsinki"],["kattomaalaus","espoo"],["kattomaalaus","vantaa"],["ulkomaalaus","helsinki"],["ulkomaalaus","espoo"],["ulkomaalaus","vantaa"]],r={"talon-maalaus":"Kokonaisuus alkaa pintojen kuntotarkastuksesta ja esityöarviosta. Pesu, irtoavan maalin poisto, korjaukset ja pohjustus tehdään ennen varsinaista maalausta kohteen tarpeen mukaan.",sisamaalaus:"Sisämaalauksessa huomioimme tilan käytön, pintamateriaalit, kalusteiden suojauksen ja asiakkaan aikataulun. Työ voidaan suunnitella koko asuntoon tai yksittäisiin huoneisiin.",julkisivumaalaus:"Julkisivumaalauksen tärkein vaihe on oikea esikäsittely. Arvioimme alustan, poistamme irtoavan pinnoitteen ja valitsemme julkisivulle sopivan pohjustuksen ja pintamaalin.",kattomaalaus:"Kattomaalauksessa tarkistamme katon materiaalin ja pinnan kunnon ennen työn aloittamista. Tarvittavat puhdistus-, kaapimis- ja pohjustustyöt tehdään ennen uutta pinnoitetta.",ulkomaalaus:"Ulkomaalaus suunnitellaan Suomen sääolosuhteisiin sopivaksi. Kohteen pesu, suojaus, esikäsittely ja maalaus ajoitetaan materiaalin ja sään mukaan kestävän lopputuloksen saavuttamiseksi."},p={helsinki:"Helsingissä kohteiden ikä, rakennustyyppi ja ympäristö vaihtelevat paljon. Siksi arvio tehdään aina kohdekohtaisesti eikä pelkän neliömäärän perusteella.",espoo:"Espoossa palvelemme omakotitaloja, rivitaloja, asuntoja ja yritysten toimitiloja. Kohteen sijainti ja pintojen kunto huomioidaan jo tarjousvaiheessa.",vantaa:"Vantaalla palvelemme sekä pientaloja että yritys- ja kiinteistökohteita. Sovimme työn rajauksen, valmistelut ja aikataulun selkeästi ennen toteutusta."},v=m.flatMap(([t,i])=>{const s=u(t),a=k(i);if(!s||!a)return[];const e=`${s.title.toLowerCase()} ${a.name}`,n=`${t}-${i}`,o=r[t]??s.description,l=p[i]??a.localFacts;return[{slug:n,serviceSlug:t,citySlug:i,keyword:e,title:`${s.title} ${a.name}`,description:`${s.title} ${a.locative} – kohdekohtainen arvio, huolellinen esikäsittely ja siisti toteutus. Maalaus Multiväri palvelee kotitalouksia, yrityksiä ja kiinteistöjä ${a.locative}. Pyydä ilmainen tarjous.`,intro:`${s.title} ${a.locative} suunnitellaan kohteen, pintamateriaalin ja aikataulun mukaan. ${a.description}`,localAngle:`${o} ${l}`}]}),c=t=>v.find(i=>i.slug===t);export{c as g};
